{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshments and accessible TV control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "person",
        "entity_kind": "OBJECT",
        "function": "Beneficiary of the refreshment setting and TV viewing experience",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "Human",
          "Guest",
          "Visitor"
        ],
        "required_properties": [
          "Seated or positioned to watch television",
          "Within proximity of refreshment setting"
        ]
      },
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "Container or vessel for drink or food",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "Cup",
          "Mug",
          "Bowl",
          "Glass"
        ],
        "required_properties": [
          "Holds refreshment",
          "Portable"
        ]
      },
      {
        "id": "support_surface",
        "entity_kind": "OBJECT",
        "function": "Stable platform to hold refreshment item",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "Side table",
          "End table",
          "Tray",
          "Small table"
        ],
        "required_properties": [
          "Flat surface",
          "Located near seating"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device used to operate the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "Remote control",
          "Control panel",
          "Handheld device"
        ],
        "required_properties": [
          "Operates television"
        ]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Screen displaying content for viewing",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "TV screen",
          "Monitor"
        ],
        "required_properties": [
          "Mounted or placed on wall/furniture"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_placement",
        "relation": "Refreshment Item is placed on Support Surface",
        "participant_roles": [
          "refreshment_item",
          "support_surface"
        ]
      ,
        "required": true
      },
      {
        "id": "proximity_to_person",
        "relation": "Support Surface is located near Person",
        "participant_roles": [
          "support_surface",
          "person"
        ]
      ,
        "required": true
      },
      {
        "id": "accessibility",
        "relation": "Entertainment Control is accessible to Person 1 and Person 2",
        "participant_roles": [
          "entertainment_control",
          "person",
          "person"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "setup_refreshments",
        "operation": "Place Refreshment Item on Support Surface near Person",
        "participant_roles": [
          "refreshment_item",
          "support_surface",
          "person"
        ],
        "operation_count": 2
      },
      {
        "id": "position_control",
        "operation": "Move Entertainment Control to Accessible Location",
        "participant_roles": [
          "entertainment_control",
          "person"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "person": [],
      "refreshment_item": [
        {
          "label": "Red cups",
          "visual_description": "Two red mugs/cups sitting on the desk in the foreground"
        },
        {
          "label": "White dish",
          "visual_description": "White plate or bowl on the desk in the foreground"
        }
      ],
      "support_surface": [
        {
          "label": "Side tables",
          "visual_description": "Wooden side tables next to the chairs"
        },
        {
          "label": "Coffee table",
          "visual_description": "Low table in the center of the seating area"
        },
        {
          "label": "Desk",
          "visual_description": "Large wooden desk in the foreground holding items"
        },
        {
          "label": "Console table",
          "visual_description": "Table against the wall under the TV"
        }
      ],
      "entertainment_control": [
        {
          "label": "Remote control",
          "visual_description": "Black rectangular object on the desk in the foreground"
        }
      ],
      "television": [
        {
          "label": "Wall mounted TV",
          "visual_description": "Black rectangular screen mounted on the wall"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_surface",
        "label": "Foreground Desk Surface",
        "visual_description": "Top of the desk containing cups and remote",
        "reason": "Contains current location of refreshment items and entertainment control; likely source for moving items."
      },
      {
        "id": "side_tables",
        "label": "Side Tables",
        "visual_description": "Tables next to the armchairs",
        "reason": "Potential destination surfaces for refreshment items."
      },
      {
        "id": "coffee_table",
        "label": "Coffee Table",
        "visual_description": "Central low table",
        "reason": "Potential destination for entertainment control or additional refreshments."
      },
      {
        "id": "under_furniture",
        "label": "Under Furniture Areas",
        "visual_description": "Space beneath desk and coffee table",
        "reason": "May contain hidden supplies or storage."
      }
    ],
    "inspection_order": [
      "desk_surface",
      "side_tables",
      "coffee_table",
      "under_furniture"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
